pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount, uint256 preBalance) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(preBalance > 0);
        vm.assume(address(this).balance >= amount);
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 recorded;
        try c.getBalance(address(this)) returns (uint256 __r) { recorded = __r; } catch { return; }
        uint cBalBefore = address(c).balance;
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted &&
            c.getBalance(address(this)) == 0 &&
            cBalBefore >= recorded &&
            address(c).balance == cBalBefore - recorded);
    }

    function testFuzz_run(uint256 amount, uint256 preBalance) public {
        _run(amount, preBalance);
    }

    receive() external payable {}
}
